import{c as t,Q as a,j as r,m as i}from"./chunks/framework.BPKcPtvA.js";const h=JSON.parse('{"title":"Asset Recovery Guide - Spot, Perp, Vault & Staked HYPE","description":"Detailed guide on how the bot handles different asset types: converting spot assets, closing perpetual positions, and handling locked vaults and HYPE staking rewards.","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://hyperliquidrecoverybot.github.io/en/asset-recovery"}],["link",{"rel":"alternate","hreflang":"en","href":"https://hyperliquidrecoverybot.github.io/en/asset-recovery"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://hyperliquidrecoverybot.github.io/zh/asset-recovery"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://hyperliquidrecoverybot.github.io/en/asset-recovery"}],["meta",{"name":"keywords","content":"HYPE unstaking, Hyperliquid vault recovery, close perp positions, Hyperliquid spot swap, claim staked HYPE"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"Asset Recovery Guide - Spot, Perp, Vault & Staked HYPE"}],["meta",{"property":"og:description","content":"Detailed guide on how the bot handles different asset types: converting spot assets, closing perpetual positions, and handling locked vaults and HYPE staking rewards."}],["meta",{"property":"og:url","content":"https://hyperliquidrecoverybot.github.io/en/asset-recovery"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"Asset Recovery Guide - Spot, Perp, Vault & Staked HYPE"}],["meta",{"name":"twitter:description","content":"Detailed guide on how the bot handles different asset types: converting spot assets, closing perpetual positions, and handling locked vaults and HYPE staking rewards."}]]},"headers":[],"relativePath":"en/asset-recovery.md","filePath":"en/asset-recovery.md","lastUpdated":null}'),s={name:"en/asset-recovery.md"};function n(o,e,l,d,u,c){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="hyperliquid-asset-extraction-emergency-withdrawal-workflow" tabindex="-1">Hyperliquid Asset Extraction: Emergency Withdrawal Workflow <a class="header-anchor" href="#hyperliquid-asset-extraction-emergency-withdrawal-workflow" aria-label="Permalink to &quot;Hyperliquid Asset Extraction: Emergency Withdrawal Workflow&quot;">​</a></h1><p>The Asset Recovery pipeline provides an automated safeguard to extract stuck funds from a flagged Hyperliquid address and execute an emergency withdrawal to your Arbitrum wallet.</p><h2 id="inputs-required" tabindex="-1">Inputs Required <a class="header-anchor" href="#inputs-required" aria-label="Permalink to &quot;Inputs Required&quot;">​</a></h2><p>Prepare the following before execution:</p><ol><li>Source address (flagged address)</li><li>Private key or mnemonic (signing only)</li></ol><h2 id="standard-7-step-pipeline" tabindex="-1">Standard 7-Step Pipeline <a class="header-anchor" href="#standard-7-step-pipeline" aria-label="Permalink to &quot;Standard 7-Step Pipeline&quot;">​</a></h2><p>The bot generates and executes steps based on detected assets. Ineligible steps are skipped automatically.</p><ol><li>Check account status</li><li>Convert spot assets (non-USDC -&gt; USDC)</li><li>Close or convert perpetual positions as needed</li><li>Withdraw vault assets that are currently available</li><li>Handle staking and withdrawable balance</li><li>Collect service fee</li><li>Complete final withdrawal</li></ol><h2 id="step-behavior" tabindex="-1">Step Behavior <a class="header-anchor" href="#step-behavior" aria-label="Permalink to &quot;Step Behavior&quot;">​</a></h2><h3 id="_1-account-preparation-spot-and-perp" tabindex="-1">1) Account Preparation, Spot, and Perp <a class="header-anchor" href="#_1-account-preparation-spot-and-perp" aria-label="Permalink to &quot;1) Account Preparation, Spot, and Perp&quot;">​</a></h3><ul><li>Account status: if account setup requires adjustment before recovery, the bot handles that first.</li><li>Spot: sells non-USDC assets into USDC.</li><li>Perp: handles eligible positions and closes or converts them as needed for recovery.</li></ul><h3 id="_2-vault" tabindex="-1">2) Vault <a class="header-anchor" href="#_2-vault" aria-label="Permalink to &quot;2) Vault&quot;">​</a></h3><ul><li>Currently withdrawable assets: withdrawn in current run.</li><li>Locked assets or vault equity with no current withdrawable amount: shown as waiting/locked in preview and results, then retried after unlock or withdrawability returns.</li></ul><h3 id="_3-staking-important" tabindex="-1">3) Staking (Important) <a class="header-anchor" href="#_3-staking-important" aria-label="Permalink to &quot;3) Staking (Important)&quot;">​</a></h3><p>The bot distinguishes between already-unstaked balance, still-staked balance, and pending-withdrawal balance.</p><p>Two practical paths may occur:</p><ul><li><strong>Faster path (2 runs)</strong>: if some staking balance is already ready for the next stage, part of it can be withdrawn in the first run and the rest follows after the waiting period.</li><li><strong>Standard path (3 runs)</strong>: if the balance is still fully staked, recovery usually needs an unstake stage and then a later withdrawal stage.</li></ul><p>The bot output always includes rerun guidance based on current state.</p><h2 id="fees-and-settlement" tabindex="-1">Fees and Settlement <a class="header-anchor" href="#fees-and-settlement" aria-label="Permalink to &quot;Fees and Settlement&quot;">​</a></h2><ul><li><code>Service Fee</code>: 0.5%, minimum 1 USDC</li><li><code>Withdrawal Fees</code>: 2 USDC</li><li><code>Total Cost</code>: Service Fee + Withdrawal Fees</li><li><code>You Will Receive</code>: Estimated Recoverable Value - Total Cost</li></ul><p>See <a href="./fee-and-settlement">Fee and Settlement</a> for formulas and examples.</p><h2 id="how-to-read-results" tabindex="-1">How to Read Results <a class="header-anchor" href="#how-to-read-results" aria-label="Permalink to &quot;How to Read Results&quot;">​</a></h2><p>Execution output includes step-level status and final summary:</p><ul><li>Recovered Amount</li><li>Actual Fees</li><li>Transaction hashes for on-chain verification</li></ul><p>Note: after withdrawal submission, settlement to Arbitrum is asynchronous and depends on Hyperliquid processing speed (often several to more than ten minutes).</p><p>Status mapping is documented in <a href="./execution-status">Execution Status</a>.</p><p>If the result page says more waiting is required, follow the suggested rerun time.</p><h2 id="retry-strategy" tabindex="-1">Retry Strategy <a class="header-anchor" href="#retry-strategy" aria-label="Permalink to &quot;Retry Strategy&quot;">​</a></h2><ul><li>Network issue: rerun directly.</li><li>Lock or waiting state: rerun at suggested time.</li><li>Input mismatch (address/key): fix inputs and rerun.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li>Run address detection before recovery to confirm asset structure.</li><li>No destination input is required; withdrawal defaults to the source address on Arbitrum.</li><li>For staking or locked vault cases, set reminders and rerun at unlock windows.</li></ol>',31)])])}const m=t(s,[["render",n]]);export{h as __pageData,m as default};
